public class Test {
    static class Collector<T, R> {
        private java.util.function.Supplier<R> supplier;
        private java.util.function.BiConsumer<R, T> accumulator;
        public Collector(java.util.function.Supplier<R> s, java.util.function.BiConsumer<R, T> a) {
            supplier = s;
            accumulator = a;
        }
        public R collect(List<T> list) {
            R result = supplier.get();
            for (T t : list) {
                accumulator.accept(result, t);
            }
            return result;
        }
    }
    public static void main(String[] args) {
        Collector<String, List<String>> c = new Collector<>(ArrayList::new, List::add);
