import java.util.*;

public class Test {
    static class Retry<T> {
        private int maxAttempts;
        public Retry(int maxAttempts) { this.maxAttempts = maxAttempts; }
        public T execute(java.util.function.Supplier<T> action) {
            for (int i = 0; i < maxAttempts; i++) {
                try {
                    return action.get();
                } catch (Exception e) {
                    if (i == maxAttempts - 1) {
                        throw e;
                    }
                }
            }
            return null;
        }
    }
    public static void main(String[] args) {
        Retry<String> retry = new Retry<>(3);
        String result = retry.execute(() -> "Success");
        System.out.println(result);
    }
},Prints Success,Compilation error,Runtime error,NullPointerException

