import java.util.*;

public class Test {
    static class Batch<T> {
        private List<T> items = new ArrayList<>();
        private int batchSize;
        private java.util.function.Consumer<List<T>> processor;
        public Batch(int batchSize, java.util.function.Consumer<List<T>> processor) {
            this.batchSize = batchSize;
            this.processor = processor;
        }
        public void add(T item) {
            items.add(item);
            if (items.size() >= batchSize) {
                flush();
            }
        }
        public void flush() {
            if (!items.isEmpty()) {
                processor.accept(new ArrayList<>(items));
                items.clear();
            }
        }
    }
    public static void main(String[] args) {
        Batch<String> batch = new Batch<>(3, list -> System.out.print(list.size()));
        batch.add("A");
        batch.add("B");
        batch.add("C");
    }
},Prints 3,Compilation error,Runtime error,Prints 0

