import java.util.*;

public class Test {
    static class Switch<T, R> {
        private Map<T, R> cases = new HashMap<>();
        private R defaultValue;
        public Switch<T, R> addCase(T condition, R result) {
            cases.put(condition, result);
            return this;
        }
        public Switch<T, R> setDefault(R result) {
            defaultValue = result;
            return this;
        }
        public R evaluate(T value) {
            return cases.getOrDefault(value, defaultValue);
        }
    }
    public static void main(String[] args) {
        Switch<String, Integer> sw = new Switch<String, Integer>()
            .addCase("one", 1)
            .addCase("two", 2)
            .setDefault(0);
        System.out.println(sw.evaluate("two"));
    }
},Prints 2,Compilation error,Runtime error,Prints 0

