public class Test {
    public static <T> Optional<T> findMin(List<T> list, Comparator<T> comparator) {
        if (list.isEmpty()) return Optional.empty();
        T min = list.get(0);
        for (T t : list) {
            if (comparator.compare(t, min) < 0) {
                min = t;
            }
        }
        return Optional.of(min);
    }
    public static void main(String[] args) {
        List<Integer> list = Arrays.asList(3, 1, 4, 1, 5);
        System.out.println(findMin(list, Integer::compare).orElse(0));
    }
},Prints 1,Compilation error,Runtime error,Prints 0

