public class Test {
    static class Filter<T> {
        private List<java.util.function.Predicate<T>> predicates = new ArrayList<>();
        public Filter<T> add(java.util.function.Predicate<T> predicate) {
            predicates.add(predicate);
            return this;
        }
        public boolean test(T value) {
            for (java.util.function.Predicate<T> p : predicates) {
                if (!p.test(value)) {
                    return false;
                }
            }
            return true;
        }
    }
    public static void main(String[] args) {
        Filter<Integer> filter = new Filter<Integer>()
            .add(n -> n > 0)
            .add(n -> n < 100)
            .add(n -> n % 2 == 0);
        System.out.println(filter.test(50));
    }
},Prints true,Compilation error,Runtime error,Prints false

