public class Test {
    static class Cycler<T> {
        private List<T> items;
        private int index = 0;
        public Cycler(List<T> items) { this.items = new ArrayList<>(items); }
        public T next() {
            T item = items.get(index);
            index = (index + 1) % items.size();
            return item;
        }
    }
    public static void main(String[] args) {
        Cycler<String> cycler = new Cycler<>(Arrays.asList("A", "B", "C"));
        System.out.println(cycler.next());
    }
