import java.util.*;

public class Test {
    static class Selector<T> {
        private List<T> items;
        private java.util.function.Predicate<T> predicate;
        public Selector(List<T> items, java.util.function.Predicate<T> predicate) {
            this.items = items;
            this.predicate = predicate;
        }
        public List<T> select() {
            List<T> result = new ArrayList<>();
            for (T t : items) {
                if (predicate.test(t)) {
                    result.add(t);
                }
            }
            return result;
        }
    }
    public static void main(String[] args) {
        Selector<Integer> sel = new Selector<>(Arrays.asList(1, 2, 3, 4, 5), n -> n % 2 == 0);
        System.out.println(sel.select().size());
    }
},Prints 2,Compilation error,Runtime error,Prints 5

